import math
pose=[0.0,0.0,0.0]
mem={}
a_prev=0.0
phase='rev'
fwd_t0=0.0
last_t=None
L=2.75
lastprint=-10
def clamp(x,a,b):
    return max(a,min(b,x))
def control(obs):
    global a_prev,phase,fwd_t0,last_t,lastprint
    t=obs['t']
    mo=obs['motion']; v=mo['v_mps']; st=obs['steer_deg']
    if last_t is not None:
        d=t-last_t
        if 0<d<1:
            pose[2]+=v*math.tan(math.radians(st))/L*d
            pose[0]+=v*math.cos(pose[2])*d
            pose[1]+=v*math.sin(pose[2])*d
    last_t=t
    X,Y,TH=pose
    c,s=math.cos(TH),math.sin(TH)
    views=obs.get('views') or {}
    for name,vw in views.items():
        if not vw: continue
        o=vw.get('origin')
        if not o: continue
        for p in (vw.get('walls') or []):
            b,dd=p[0],p[1]
            px=o[0]+dd*math.cos(math.radians(b)); py=o[1]+dd*math.sin(math.radians(b))
            wx=X+c*px-s*py; wy=Y+s*px+c*py
            mem[(int(round(wx*5)),int(round(wy*5)))]=(wx,wy,t)
    if len(mem)>1500:
        for k in [k for k,m in mem.items() if t-m[2]>15]:
            del mem[k]
    rig=obs['rig']; R=rig['trailer_rear']; th=math.radians(rig['trailer_heading_deg'])
    bx,by=-math.cos(th),-math.sin(th); nx,ny=-math.sin(th),math.cos(th)
    pts=[]
    for (wx,wy,tt) in mem.values():
        dx=wx-X; dy=wy-Y
        px=c*dx+s*dy; py=-s*dx+c*dy
        qx=px-R[0]; qy=py-R[1]
        u=qx*bx+qy*by; w=qx*nx+qy*ny
        if -1.0<u<10 and abs(w)<10:
            pts.append((u,w))
    tgt=obs.get('target') or {}
    at=None
    if tgt.get('in_sight') and tgt.get('bearing_deg') is not None:
        e=rig['eye']; bb=math.radians(tgt['bearing_deg']); dd=tgt['dist_m']
        px=e[0]+dd*math.cos(bb)-R[0]; py=e[1]+dd*math.sin(bb)-R[1]
        tu=px*bx+py*by; tw=px*nx+py*ny
        if tu>0.5: at=math.degrees(math.atan2(tw,tu))
    best=None; bests=-1e9; free0=9.0; maxfree=0
    for a in range(-60,61,5):
        ca=math.cos(math.radians(a)); sa=math.sin(math.radians(a))
        free=9.0
        lst=[]
        for (u,w) in pts:
            al=u*ca+w*sa
            if al<=0 or al>9: continue
            lat=-u*sa+w*ca
            lst.append((al,abs(lat)))
            if abs(lat)<1.15 and al<free: free=al
        clr=3.0
        lim=min(free,5.0)
        for al,la in lst:
            if al<lim and la<clr: clr=la
        if a==0: free0=free
        maxfree=max(maxfree,free)
        sc=free-0.02*abs(a)+0.8*clr-0.01*abs(a-a_prev)
        if at is not None: sc-=0.03*abs(a-at)
        if sc>bests: bests=sc; best=a
    a_prev=0.7*a_prev+0.3*best
    h=obs['hitch_deg']
    status=obs.get('status')
    look=rig.get('screen_gaze_deg')
    if look is None: look=-168
    cyc=t%4.4
    mir=rig.get('mirrors') or {}
    if 1.6<=cyc<2.2: look=mir.get('left_mirror',43)
    elif 3.8<=cyc: look=mir.get('right_mirror',-65)
    if phase=='rev' and (abs(h)>45 or status=='JACKKNIFED'):
        phase='fwd'; fwd_t0=t; wake('pulling forward, hitch %.0f'%h)
    if phase=='fwd':
        if abs(h)<8 and t-fwd_t0>2.0:
            phase='rev'
        else:
            return (0.0,1.0,look)
    h_des=clamp(0.9*a_prev,-35,35)
    steer=clamp(2.0*(h-h_des)-0.75*h_des,-34,34)
    rem=obs['progress']['remaining']
    spd=-1.0
    if free0<2.5 or rem<4: spd=-0.6
    if t-lastprint>2:
        lastprint=t
        print('t%.1f rem%.1f a%.0f best%s at%s h%.1f hd%.1f st%.1f free0%.1f npts%d'%(t,rem,a_prev,best,at,h,h_des,steer,free0,len(pts)))
    return (steer,spd,look)

