PTS={}
TGT=None
mode='rev'
hd_f=0.0
look_i=0
look_t=0.0
LOOKS=[64,-64,-160,-64,64,160]
HOLD=0.6
last_t=None
n=0
def wrap(a):
    while a>180:a-=360
    while a<-180:a+=360
    return a
def clamp(v,a,b):
    return max(a,min(b,v))
def tow(px,py):
    c=math.cos(TH);s=math.sin(TH)
    return (X+c*px-s*py, Y+s*px+c*py)
def control(obs):
    global X,Y,TH,TGT,mode,hd_f,look_i,look_t,n
    n+=1
    dt=obs.get('dt',0.1) or 0.1
    mo=obs['motion'];v=mo['v_mps'];st=obs['steer_deg']
    X+=v*math.cos(TH)*dt;Y+=v*math.sin(TH)*dt;TH+=v*math.tan(math.radians(st))/2.5*dt
    t=obs['t']
    views=obs.get('views') or {}
    for k,vw in views.items():
        o=vw['origin']
        for b,d in vw.get('walls',[]):
            if d>18: continue
            px=o[0]+d*math.cos(math.radians(b));py=o[1]+d*math.sin(math.radians(b))
            wx,wy=tow(px,py)
            PTS[(int(round(wx*4)),int(round(wy*4)))]=(wx,wy,t)
    if len(PTS)>2500:
        items=sorted(PTS.items(),key=lambda kv:kv[1][2])
        for kk,_ in items[:500]: del PTS[kk]
    tg=obs.get('target') or {}
    if tg.get('in_sight') and tg.get('dist_m') is not None:
        b=math.radians(tg['bearing_deg']);d=tg['dist_m']
        TGT=tow(0.75+d*math.cos(b),d*math.sin(b))
    rig=obs['rig'];hz=rig['hitch'];rr=rig['trailer_rear']
    back=math.degrees(math.atan2(rr[1]-hz[1],rr[0]-hz[0]))
    Rx,Ry=tow(rr[0],rr[1])
    phi=math.degrees(TH)+back
    near=[]
    for (wx,wy,tt) in PTS.values():
        dx=wx-Rx;dy=wy-Ry
        if dx*dx+dy*dy<196: near.append((dx,dy))
    angs=list(range(-70,71,5));free=[]
    for a in angs:
        p=math.radians(phi+a);c=math.cos(p);s=math.sin(p);f=10.0
        for dx,dy in near:
            sa=dx*c+dy*s
            if sa>0.2 and sa<f:
                l=-dx*s+dy*c
                if abs(l)<1.55: f=sa
        free.append(f)
    mx=max(free);th_=min(mx,8.0)-0.4
    best=None;grp=[]
    groups=[];cur=[]
    for a,f in zip(angs,free):
        if f>=th_: cur.append(a)
        else:
            if cur: groups.append(cur);cur=[]
    if cur: groups.append(cur)
    groups.sort(key=lambda g:(-len(g),abs(sum(g)/len(g))))
    asel=sum(groups[0])/len(groups[0]) if groups else 0.0
    rem=obs['progress']['remaining']
    if TGT is not None:
        dx=TGT[0]-Rx;dy=TGT[1]-Ry;dd=math.hypot(dx,dy)
        if dd<12:
            at=wrap(math.degrees(math.atan2(dy,dx))-phi)
            if abs(at)<=70:
                i=int(round((at+70)/5));i=clamp(i,0,len(angs)-1)
                if free[i]>=min(dd-0.5,6) : asel=at*0.7 if dd>3 else at*0.4
    hitch=obs['hitch_deg']
    hd=clamp(-0.8*asel,-30,30)
    hd_f+=0.3*(hd-hd_f)
    # head
    hdh=obs['head']
    if hdh.get('settled'):
        look_t+=dt
        if look_t>=HOLD:
            look_i=(look_i+1)%len(LOOKS);look_t=0.0
    look=LOOKS[look_i]
    if mode=='rev' and abs(hitch)>45:
        mode='fwd';print('fwd recover',t,hitch)
    if mode=='fwd':
        if abs(hitch)<8: mode='rev'
        return (clamp(-1.5*hitch,-40,40),1.2,look)
    steer=clamp(2.5*(hitch-hd_f),-45,45)
    sp=-0.8
    if mx<2.5: sp=-0.5
    if rem<6: sp=-0.5
    if n%20==0: print('t%.0f a%.0f mx%.1f h%.0f hd%.0f st%.0f rem%.1f np%d'%(t,asel,mx,hitch,hd_f,steer,rem,len(near)))
    return (steer,sp,look)

