            p=w(e[0]+d*math.cos(b), e[1]+d*math.sin(b))
            if bay is None: bay=p
            else: bay=(0.9*bay[0]+0.1*p[0], 0.9*bay[1]+0.1*p[1])
            wk('bay','TARGET seen at %.1fm bearing %.0f'%(d,tg['bearing_deg']))
    except Exception:
        pass
